function newFlight(){let a=airlines[rand(0,airlines.length-1)];world.flight={code:a[0]+' '+rand(1000,9999),carrier:a[1],destination:cities[rand(0,cities.length-1)],type:planeTypes[rand(0,planeTypes.length-1)]};$('flightNo').textContent=world.flight.code;$('route').textContent='MADRID → '+world.flight.destination;$('aircraft').textContent=world.flight.type;world.totalPax=rand(64,112);world.bagCount=rand(8,13);$('passengers').textContent=world.totalPax;}
