function beep(freq=520,dur=.08,type='sine'){try{if(!soundOn)return;audio??=new(window.AudioContext||window.webkitAudioContext)();let o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(.055,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+dur);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+dur)}catch{}}
function announce(text,alert=false){ui.toast.textContent=(alert?'⚠ ':'✦ ')+text;ui.toast.classList.add('show');clearTimeout(messageTimer);messageTimer=setTimeout(()=>ui.toast.classList.remove('show'),2600);if(alert)beep(330,.22,'triangle');else beep(620,.07);}
