 {name:'CIERRE',title:'Asegura las bodegas',detail:'Verifica la carga y cierra las puertas de equipaje.',next:'Retirar equipos'},
 {name:'PUSHBACK',title:'Despeja la plataforma',detail:'La cuadrilla retira el equipo. Después autoriza el pushback.',next:'Salida'},
