function setPhase(n){world.phase=n;world.phaseTime=0;let p=phases[n];ui.phase.textContent=p.name;ui.title.textContent=p.title;ui.detail.textContent=p.detail;ui.next.textContent=p.next;ui.progress.style.width=(n/(phases.length-1)*100)+'%';ui.count.textContent=(n+1)+' / '+phases.length+' tareas';setObjective();}
function setObjective(){const texts=['Sigue la señalización de entrada y espera el estacionamiento','Acércate al tren delantero para colocar los calzos','Observa cómo la escalera se aproxima al avión','Acércate a la bodega lateral para abrir la puerta','La cuadrilla mueve maletas una por una hasta el carro','Acércate al pasajero con el icono de asistencia','Coordina el embarque y la carga del vuelo de salida','Acércate a cada bodega para asegurar las puertas','Espera a que el equipo regrese a su zona de estacionamiento','Acércate al tractor de pushback para autorizar la salida'];ui.objective.textContent=texts[world.phase]||'Operación completa';}
function targetForInteraction(){let candidates=[];if(world.phase===1&&!chocks[0].placed)candidates.push({x:940,y:463,label:'COLOCAR CALZOS',icon:'⬟',kind:'chock',range:85});if(world.phase===3&&world.doors[0]===false)candidates.push({x:684,y:482,label:'ABRIR BODEGA',icon:'↗',kind:'doorOpen',range:95});if(world.phase===5&&!world.assistDone&&world.assistTriggered)candidates.push({x:passengers.find(p=>p.assist)?.x||760,y:passengers.find(p=>p.assist)?.y||550,label:'ASISTIR PASAJERO',icon:'＋',kind:'assist',range:90});if(world.phase===6&&world.paxIn>=passengers.filter(p=>p.type==='departure').length&&world.loaded>=inboundBags.length&&inboundBags.length>0)candidates.push({x:684,y:482,label:'CERRAR BODEGA',icon:'▱',kind:'doorClose',range:95});if(world.phase===9)candidates.push({x:tug.x,y:tug.y,label:'AUTORIZAR PUSHBACK',icon:'➜',kind:'push',range:95});
 if(world.carried)candidates.unshift({x:player.x+Math.cos(player.dir)*27,y:player.y+Math.sin(player.dir)*27,label:'SOLTAR EQUIPAJE',icon:'▣',kind:'drop',range:75});else if(world.phase===4||world.phase===6){let b=bags.find(b=>b.state==='cart'&&!b.claimed)||inboundBags.find(b=>b.state==='cart'&&!b.claimed);if(b)candidates.unshift({x:b.x,y:b.y,label:'MANIPULAR MALETA',icon:'▣',kind:'bag',range:52});}
 let best=null,bd=Infinity;for(const c of candidates){let d=dist(player,c);if(d<c.range&&d<bd){bd=d;best=c;}}return best;}

