function doInteract(){let hit=targetForInteraction();if(!hit){if(world.carried){dropBag();return}if(world.phase===4||world.phase===6){let b=bags.find(b=>b.state==='cart'&&!b.claimed)||inboundBags.find(b=>b.state==='cart'&&!b.claimed);if(b&&dist(player,b)<95){b.claimed=true;world.carried=b;announce('Maleta recogida · '+b.weight+' kg');return}}note('Acércate al equipo o al punto de operación');return}
 switch(hit.kind){case'chock':chocks.forEach(c=>c.placed=true);agents[1].state='chocksDone';agents[1].target={x:930,y:550};setPhase(2);stairs.state='approach';belt.state='approach';agents[2].state='driveStairs';agents[2].target={x:stairs.tx,y:stairs.ty+35};agents[3].state='driveBelt';agents[3].target={x:belt.tx,y:belt.ty+40};announce('Calzos instalados · escalera y banda en aproximación');break;
 case'doorOpen':world.doors[0]=true;world.doors[1]=true;setPhase(4);world.phaseTime=0;announce('Bodegas abiertas · comienza la descarga');agents[3].state='unload';agents[1].state='guide';break;
 case'assist':world.assistDone=true;let ap=passengers.find(p=>p.assist);if(ap){ap.state='assisted';ap.target={x:1090,y:370};}agents[5].state='assistDone';announce('Asistencia solicitada · pasajero acompañado');setPhase(6);startBoarding();break;
 case'doorClose':world.doors=[false,false];setPhase(8);stairs.state='return';belt.state='return';tug.state='return';agents[2].state='returnStairs';agents[3].state='returnBelt';agents[4].state='returnTug';announce('Bodegas aseguradas · retirada de equipos');break;
 case'push':world.pushStarted=true;world.phaseTime=0;agents.forEach((a,i)=>{a.state='signal';a.target={x:650+i*30,y:560+(i%2)*30}});tug.state='pushApproach';announce('Pushback autorizado · tractor conectando');setPhase(10);break;
 case'bag':let found=bags.find(b=>b.state==='cart'&&!b.claimed)||inboundBags.find(b=>b.state==='cart'&&!b.claimed);if(found){found.claimed=true;world.carried=found;announce('Maleta recogida · '+found.weight+' kg')}break;
 case'drop':dropBag();break;}
}
function dropBag(){let b=world.carried;if(!b)return;world.carried=null;b.x=player.x+Math.cos(player.dir)*27;b.y=player.y+Math.sin(player.dir)*27;b.claimed=false;if(world.phase===4){b.state='conveyor';b.t=0;b.from={x:b.x,y:b.y};b.to={x:465,y:585};}else if(world.phase===6){b.state='loading';b.t=0;b.from={x:b.x,y:b.y};b.to={x:685,y:474};}else b.state='cart';announce('Maleta colocada');}
function startBoarding(){world.boarding=true;world.paxIn=0;let count=rand(7,10);for(let i=0;i<count;i++){let p={x:1085+(i%4)*19,y:355+Math.floor(i/4)*24,target:{x:740,y:495},state:'boarding',type:'departure',color:['#c9a177','#8da6ba','#c58b77','#dabd72'][i%4],speed:23+Math.random()*12,assist:false,wait:i*.52};passengers.push(p);}for(let i=0;i<world.bagCount;i++)inboundBags.push({id:i,x:370+(i%4)*17,y:605,from:{x:370+(i%4)*17,y:605},to:{x:684,y:474},color:['#d5785b','#5999bb','#dcbd55','#80b997','#a58ac9'][i%5],size:rand(10,15),state:'cart',t:0,weight:rand(8,27),claimed:false});tug.state='deliver';tug.tx=390;tug.ty=582;agents[4].state='deliver';agents[4].target={x:390,y:620};}
function setPhase(n){world.phase=n;world.phaseTime=0;let p=phases[n];ui.phase.textContent=p.name;ui.title.textContent=p.title;ui.detail.textContent=p.detail;ui.next.textContent=p.next;ui.progress.style.width=(Math.min(n,9)/9*100)+'%';ui.count.textContent=(Math.min(n+1,10))+' / 10 tareas';setObjective();}
function update(dt){if(paused||world.finished)return;elapsed+=dt;world.phaseTime+=dt;let p=targetForInteraction();ui.interactLabel.textContent=p?p.label:(world.carried?'SOLTAR':'INTERACTUAR');ui.interactIcon.textContent=p?p.icon:(world.carried?'↓':'↗');ui.interact.style.opacity=p?'1':'.76';
 // Character movement (keyboard and touch joystick)
 let ix=(keys.ArrowRight||keys.d?1:0)-(keys.ArrowLeft||keys.a?1:0)+stick.x,iy=(keys.ArrowDown||keys.s?1:0)-(keys.ArrowUp||keys.w?1:0)+stick.y;let mag=Math.hypot(ix,iy);if(mag>1){ix/=mag;iy/=mag;}let speed=(run?210:132)*(world.carried?.72:1);player.vx=ix*speed;player.vy=iy*speed;let nx=player.x+player.vx*dt,ny=player.y+player.vy*dt;if(mag>.08){player.dir=Math.atan2(iy,ix);player.walk+=dt*speed*.12;}else player.walk*=.88;
 // plane and equipment as collision obstacles
 let dx=nx-world.plane.x,dy=ny-world.plane.y;let ell=(dx*dx)/(210*210)+(dy*dy)/(65*65);if(ell>1.12){player.x=clamp(nx,80,1420);player.y=clamp(ny,140,900)}
 // keep player out of solid equipment, allow reaching operation interaction points
 for(let e of [stairs,belt,tug])if(Math.abs(player.x-e.x)<e.w*.43+11&&Math.abs(player.y-e.y)<e.h*.5+10){if(Math.abs(player.x-e.x)>Math.abs(player.y-e.y))player.x-=Math.sign(player.x-e.x)*speed*dt;else player.y-=Math.sign(player.y-e.y)*speed*dt;}
 // taxi arrival moves physically into the stand
 if(world.phase===0){world.plane.x=lerp(world.plane.x,760,Math.min(1,dt*.22));world.plane.y=430;if(Math.abs(world.plane.x-760)<2&&world.phaseTime>3.5){world.plane.x=760;setPhase(1);announce('Aeronave estacionada · coloca los calzos');}}
 moveEquipment(dt);moveAgents(dt);movePassengers(dt);moveBags(dt);
 if(world.phase===2&&world.stairReady&&world.phaseTime>1.1){setPhase(3);announce('Escalera estabilizada · puertas listas');}
 if(world.phase===4){if(world.unloaded>=world.bagCount&&world.paxOut>=passengers.filter(p=>p.type==='arrival').length){if(!world.assistTriggered){world.assistTriggered=true;let ap=passengers.find(p=>p.assist);if(ap){ap.state='needsHelp';ap.x=795;ap.y=550;ap.target={x:795,y:550};}setPhase(5);announce('Se requiere asistencia para un pasajero',true);}}}
 if(world.phase===6){let dep=passengers.filter(p=>p.type==='departure');if(world.paxIn>=dep.length&&world.loaded>=inboundBags.length&&world.phaseTime>3){setPhase(7);announce('Embarque y carga completos · cierra las bodegas');}}
 if(world.phase===8&&stairs.state==='park'&&belt.state==='park'&&tug.state==='park'&&world.phaseTime>1.2){setPhase(9);announce('Plataforma despejada · solicita autorización de salida');}
 if(world.phase===10)updatePushback(dt);
 cam.x=lerp(cam.x,player.x+95,.055);cam.y=lerp(cam.y,player.y-15,.055);cam.x=clamp(cam.x,480,1000);cam.y=clamp(cam.y,280,620);
 ui.timer.textContent=fmt(elapsed);ui.bags.textContent=(world.phase<6?world.unloaded:world.loaded)+' / '+world.bagCount;ui.crew.textContent=agents.filter(a=>!['parked'].includes(a.state)).length+' activos';ui.money.textContent='$'+money.toLocaleString('en-US');}
function moveEquipment(dt){for(let e of [stairs,belt,tug])if(e.state==='approach'||e.state==='return'||e.state==='deliver'||e.state==='pushApproach'){let tx=e.state==='return'?({stairs:420,belt:430,tug:365}[e===stairs?'stairs':e===belt?'belt':'tug']):e.tx,ty=e.state==='return'?({stairs:570,belt:514,tug:615}[e===stairs?'stairs':e===belt?'belt':'tug']):e.ty;let d=Math.hypot(tx-e.x,ty-e.y),v=e===tug?53:37;if(d>2){e.x+=((tx-e.x)/d)*Math.min(d,v*dt);e.y+=((ty-e.y)/d)*Math.min(d,v*dt);e.rolling=true}else{e.x=tx;e.y=ty;e.rolling=false;if(e===stairs&&e.state==='approach'){e.state='park';world.stairReady=true}if(e===belt&&e.state==='approach'){e.state='park';world.beltReady=true}if(e.state==='return')e.state='park';if(e===tug&&e.state==='deliver')e.state='park';if(e===tug&&e.state==='pushApproach')e.state='connected';}}
 if(world.phase===8&&tug.state==='park')world.vehicleHome=true;
