function moveAgents(dt){for(let i=0;i<agents.length;i++){let a=agents[i];if(a.state==='patrol'){if(!a.target||dist(a,a.target)<8){a.target={x:rand(530,850),y:rand(545,625)}}}if(a.state==='driveStairs')a.target={x:stairs.x,y:stairs.y+28};if(a.state==='driveBelt')a.target={x:belt.x,y:belt.y+27};if(a.state==='returnStairs')a.target={x:stairs.x,y:stairs.y+28};if(a.state==='returnBelt')a.target={x:belt.x,y:belt.y+24};if(a.state==='returnTug')a.target={x:tug.x,y:tug.y+23};if(a.state==='deliver')a.target={x:tug.x,y:tug.y+23};if(a.state==='chocks')a.target={x:944,y:501};if(a.state==='guide')a.target={x:750,y:546};if(a.state==='unload')a.target={x:680,y:520};if(a.state==='signal')a.target={x:620+i*34,y:555+(i%2)*40};if(a.target){let dx=a.target.x-a.x,dy=a.target.y-a.y,d=Math.hypot(dx,dy);if(d>4){let v=a.state==='signal'?30:44;a.x+=dx/d*Math.min(d,v*dt);a.y+=dy/d*Math.min(d,v*dt);a.dir=Math.atan2(dy,dx);a.walk+=dt*6;}}if(a.state==='driveStairs'&&world.stairReady)a.state='work';if(a.state==='driveBelt'&&world.beltReady)a.state='work';if(a.state==='returnStairs'&&stairs.state==='park')a.state='standby';if(a.state==='returnBelt'&&belt.state==='park')a.state='standby';if(a.state==='returnTug'&&tug.state==='park')a.state='standby';}}
